def parse_ini(text):
    """Sections, keys and values of INI text. See TASK.md."""
    sections = {}
    current = None      # current section name; None means no section yet
    last_key = None     # last key set in the current section (for continuations)

    for i, raw in enumerate(text.split("\n")):
        n = i + 1
        # Rule 1: drop a \r that sits right before the \n.
        if raw.endswith("\r"):
            raw = raw[:-1]

        # Rule 2: blank / whitespace-only lines are skipped.
        if raw.strip() == "":
            continue

        # Rule 2 & 5: a comment starts at the first non-whitespace char.
        first = raw.lstrip()[0]
        if first == ";" or first == "#":
            continue

        # Rule 7: a line beginning with space or tab (and not blank/comment)
        # continues the value of the previous key.
        if raw[0] == " " or raw[0] == "\t":
            if last_key is None:
                raise ValueError("line %d: continuation with no preceding key" % n)
            sections[current][last_key] += "\n" + raw.strip()
            continue

        s = raw.strip()

        # Rule 3: a section header.
        if s[0] == "[":
            if not s.endswith("]"):
                raise ValueError("line %d: malformed section header" % n)
            name = s[1:-1].strip()
            if name == "":
                raise ValueError("line %d: empty section name" % n)
            if name not in sections:
                sections[name] = {}
            current = name
            last_key = None
            continue

        # Rule 4: key = value (split at the first '=').
        if "=" in s:
            key, _, val = s.partition("=")
            key = key.strip().lower()
            val = val.strip()
            if key == "":
                raise ValueError("line %d: empty key" % n)
            if current is None:
                current = ""
                sections[current] = {}
            sections[current][key] = val
            last_key = key
            continue

        # Rule 10: anything else is an error.
        raise ValueError("line %d: not a section, key=value, or continuation" % n)

    return sections
